#!/usr/bin/env python3
"""Run maintained Pump handler suites against one independently compiled ELF."""
import argparse,gzip,hashlib,json,subprocess,sys,tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SUITES=[('volume','pump_validate_volume.py'),('administration','pump_validate_admin.py'),('authority','pump_validate_authority.py'),('configuration','pump_validate_config_admin.py'),('buy','pump_validate_buy.py'),('sell','pump_validate_sell.py'),('quote','pump_validate_quote.py'),('creator_collection','pump_creator_collect_differential.py'),('creator_distribution','pump_creator_distribution_differential.py'),('minimum_distribution','pump_minimum_fee_differential.py'),('creator_collection_v2','pump_creator_collect_v2_differential.py'),('extension','pump_extend_differential.py'),('volume_sync','pump_volume_sync_differential.py'),('fee_sweeps','pump_fee_sweep_differential.py'),('creator_migration','pump_creator_migration_differential.py'),('admin_cto','pump_admin_cto_differential.py'),('set_params','pump_set_params_differential.py'),('set_creator','pump_set_creator_differential.py'),('idl_authority','pump_idl_authority_differential.py'),('legacy_create','pump_create_differential.py'),('exact_quote_v3','pump_exact_quote_differential.py'),('create_v2','pump_create_quote_differential.py'),('legacy_sell','pump_legacy_sell_differential.py'),('legacy_sell_configured_fee','pump_legacy_sell_configured_fee_differential.py'),('sell_v2','pump_sell_v2_differential.py'),('create_control','pump_create_control_differential.py'),('migration','pump_migrate_differential.py'),('v3_configured_fee','pump_v3_configured_fee_differential.py')]
def main():
 p=argparse.ArgumentParser();p.add_argument('--candidate',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();candidate=a.candidate.resolve();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();original_sha=sha(ROOT/'evidence/original/pump/deployed.so');candidate_sha=sha(candidate);suites={};scripts={}
 with tempfile.TemporaryDirectory(prefix='pump-differential-') as tmp:
  for name,filename in SUITES:
   script=ROOT/'scripts'/filename;before=sha(script);output=Path(tmp)/(name+'.json');subprocess.run([sys.executable,str(script),'--candidate',str(candidate),'--output',str(output)],check=True,cwd=ROOT)
   assert before==sha(script),f'harness changed during execution: {filename}'
   assert candidate_sha==sha(candidate),'candidate changed during execution'
   raw=output.read_bytes();result=json.loads(gzip.decompress(raw) if raw.startswith(b'\x1f\x8b') else raw);assert result.get('original_sha256',result.get('provenance',{}).get(str(ROOT/'evidence/original/pump/deployed.so')))==original_sha and result.get('candidate_sha256',result.get('provenance',{}).get(str(candidate)))==candidate_sha
   result.setdefault('case_count',len(result['cases']));suites[name]=result;scripts[filename]=before
   retained=a.output.parent/(a.output.name+'.suites');retained.mkdir(parents=True,exist_ok=True);(retained/(name+'.json.gz')).write_bytes(gzip.compress(json.dumps(result,separators=(',',':')).encode(),mtime=0))
 report={'scope':'Thirty-three recovered handlers plus partial buy_v3/sell_v3/buy_exact_quote_in_v3/create_v2 paths. Bounded local differential evidence, not full source recovery or binary identity. Per-suite limits are preserved.','original_sha256':original_sha,'candidate_sha256':candidate_sha,'script_sha256':scripts,'case_count':sum(s['case_count'] for s in suites.values()),'mismatches':[f'{name}: {failure}' for name,suite in suites.items() for failure in suite.get('mismatches',suite.get('failures',[]))],'suites':suites}
 raw=(json.dumps(report,separators=(',',':'))+'\n').encode();a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_bytes(gzip.compress(raw,mtime=0) if a.output.suffix=='.gz' else raw);print(json.dumps({'cases':report['case_count'],'mismatches':report['mismatches']}));assert not report['mismatches']
if __name__=='__main__':main()
